#include <array>
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <unordered_set>
#include <vector>
constexpr int PAIRS[6][2]={{0,1},{0,2},{0,3},{1,2},{1,3},{2,3}};
using S=std::array<uint16_t,14>; using A=std::array<int8_t,14>;
struct Hash{size_t operator()(S const&s)const noexcept{uint64_t h=1469598103934665603ULL;for(auto x:s){h^=x;h*=1099511628211ULL;}return h;}};
const std::array<int,7> hp={1,2,3,4,0,6,5},pp={4,5,6,1,3,2,0}; const std::array<int,14>opts={2,2,2,2,2,2,2,2,2,2,2,5,0,2};
S centre(){S s{};for(int sr=0;sr<14;sr++){int o=sr/7,u=sr%7,z=o?pp[u]:u;int ad[4]={z,hp[z],7+z,7+hp[z]};int r=7*o+z;for(int k=0;k<2;k++)s[r]|=1u<<ad[PAIRS[opts[sr]][k]];}return s;}
std::array<uint16_t,14> host(){std::array<uint16_t,14>x{};for(int o=0;o<2;o++)for(int z=0;z<7;z++)x[7*o+z]=(1u<<z)|(1u<<hp[z])|(1u<<(7+z))|(1u<<(7+hp[z]));return x;}
struct E{S s;std::array<uint16_t,14>h{},at{};std::unordered_set<S,Hash>ns;std::vector<int>rs,cs;int st;void dfs(int r,uint16_t ur,uint16_t uc){uint16_t u=h[r]&~s[r];while(u){int c=__builtin_ctz(u);u&=u-1;if(uc>>c&1)continue;uint16_t q=at[c];while(q){int rr=__builtin_ctz(q);q&=q-1;if(rr==st){if(rs.size()<2)continue;S f=s;for(size_t i=0;i<cs.size();i++){int oc=cs[i];f[rs[i]]^=1u<<oc;f[rs[i+1]]^=1u<<oc;}f[rs.back()]^=1u<<c;f[st]^=1u<<c;ns.insert(f);}else if(!(ur>>rr&1)&&rr>=st){rs.push_back(rr);cs.push_back(c);dfs(rr,ur|(1u<<rr),uc|(1u<<c));cs.pop_back();rs.pop_back();}}}}void run(){at.fill(0);ns.clear();for(int c=0;c<14;c++)for(int r=0;r<14;r++)if(s[r]>>c&1)at[c]|=1u<<r;for(st=0;st<14;st++){rs={st};cs.clear();dfs(st,1u<<st,0);}}};
int supp(const S&a,const S&b){int d=0;for(int r=0;r<14;r++)d+=__builtin_popcount(a[r]^b[r]);return d;}
struct P{int x,y;};inline int det(P a,P b,P c){return(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);}
struct TopEnum{std::array<uint16_t,7>sig{};std::array<int8_t,14>asg{};std::array<uint8_t,2>used{};std::vector<A>sol;int mode=0;uint64_t nodes=0;bool clean_partial()const{std::array<P,14>p{};int n=0;for(int r=0;r<7;r++){uint16_t m=sig[r];while(m){int c=__builtin_ctz(m);m&=m-1;if(asg[c]>=0){int y=mode==0?7*(c/7)+asg[c]:2*asg[c]+c/7;p[n++]={r,y};}}}for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)for(int k=j+1;k<n;k++)if(det(p[i],p[j],p[k])==0)return false;return true;}void dfs(int d){nodes++;if(d==14){sol.push_back(asg);return;}int bv=-1,best=8;std::array<int8_t,7>dom{};int dc=0;for(int v=0;v<14;v++)if(asg[v]<0){int g=v/7,c=0;std::array<int8_t,7>x{};for(int z=0;z<7;z++)if(!(used[g]>>z&1)){asg[v]=z;if(clean_partial())x[c++]=z;asg[v]=-1;}if(!c)return;if(c<best){best=c;bv=v;dc=c;dom=x;}}int g=bv/7;for(int i=0;i<dc;i++){int z=dom[i];asg[bv]=z;used[g]|=1u<<z;dfs(d+1);used[g]&=~(1u<<z);asg[bv]=-1;}}void run(int m){mode=m;asg.fill(-1);used.fill(0);sol.clear();nodes=0;dfs(0);}};
struct BottomGroup{std::vector<S>cand;std::array<uint16_t,14>ho;A a{};std::array<int8_t,7>r{};uint8_t used=0;int ori=0;uint64_t nodes=0;std::array<uint64_t,196>emask{};uint64_t all=0;int point(int edge)const{int row=edge/14,c=edge%14,z=row%7;int rp=row<7?z:r[z];int x=ori<2?(row<7?rp:7+rp):2*rp+(row<7?0:1);int y=ori%2==0?7*(c/7)+a[c]:2*a[c]+c/7;return 14*x+y;}uint64_t transition(int z,uint64_t active)const{std::vector<int>prior,nw;for(int rr=0;rr<7;rr++){uint16_t m=cand[0][rr];while(m){int c=__builtin_ctz(m);m&=m-1;prior.push_back(14*rr+c);}}for(int rr=7;rr<14;rr++){uint16_t m=ho[rr];while(m){int c=__builtin_ctz(m);m&=m-1;int e=14*rr+c;if(r[rr%7]<0)continue;(rr%7==z?nw:prior).push_back(e);}}for(int e:nw){int pe=point(e);for(int i=0;i<(int)prior.size();i++)for(int j=i+1;j<(int)prior.size();j++){int f=prior[i],g=prior[j],pf=point(f),pg=point(g);if(det({pe/14,pe%14},{pf/14,pf%14},{pg/14,pg%14})==0)active&=~(emask[e]&emask[f]&emask[g]);}prior.push_back(e);if(!active)break;}return active;}bool dfs(int d,uint64_t active){nodes++;if(d==7)return active!=0;int bz=-1,best=8;std::array<int8_t,7>dom{};int dc=0;for(int z=0;z<7;z++)if(r[z]<0){std::array<int8_t,7>x{};int c=0;for(int v=0;v<7;v++)if(!(used>>v&1)){r[z]=v;auto ch=transition(z,active);r[z]=-1;if(ch)x[c++]=v;}if(!c)return false;if(c<best){best=c;bz=z;dc=c;dom=x;}}for(int i=0;i<dc;i++){int v=dom[i];r[bz]=v;used|=1u<<v;auto ch=transition(bz,active);if(dfs(d+1,ch))return true;used&=~(1u<<v);r[bz]=-1;}return false;}bool solve(const std::vector<S>&cs,const A&aa,int o){cand=cs;a=aa;ori=o;ho=host();r.fill(-1);used=0;nodes=0;all=cand.size()==64?~0ULL:((1ULL<<cand.size())-1);emask.fill(0);for(int i=0;i<(int)cand.size();i++)for(int rr=0;rr<14;rr++){uint16_t m=cand[i][rr];while(m){int c=__builtin_ctz(m);m&=m-1;emask[14*rr+c]|=1ULL<<i;}}return dfs(0,all);}};
struct Shard{int first,last;std::uint64_t nodes;};
struct CacheCase{std::array<std::uint16_t,7>sig;int multiplicity;std::array<int,2>top_orders;std::array<std::uint64_t,2>top_nodes;std::array<std::vector<Shard>,4>shards;};
const std::array<CacheCase,7> CASES={{
 {{{3,768,12,3072,144,8224,4160}},46,{{65296,1584}},{{576716,39556}},{{{{{1,4081,15379},{4082,8162,16924},{8163,12243,16151},{12244,16324,17392},{16325,20405,18612},{20406,24486,17058},{24487,28567,19270},{28568,32648,17197},{32649,36729,20011},{36730,40810,19395},{40811,44891,17881},{44892,48972,18030},{48973,53053,19376},{53054,57134,18309},{57135,61215,18658},{61216,65296,21568}}},{{{1,1584,6842}}},{{{1,4081,16400},{4082,8162,15371},{8163,12243,17044},{12244,16324,16062},{16325,20405,18929},{20406,24486,17101},{24487,28567,18064},{28568,32648,20345},{32649,36729,17543},{36730,40810,20796},{40811,44891,19178},{44892,48972,18612},{48973,53053,18694},{53054,57134,18210},{57135,61215,21444},{61216,65296,20020}}},{{{1,1584,9539}}}}}},
 {{{257,6,520,3072,144,8224,4160}},46,{{22568,36760}},{{331714,420464}},{{{{{1,22568,96550}}},{{{1,18000,72995},{18001,36760,79594}}},{{{1,22568,94773}}},{{{1,18000,79151},{18001,36760,81988}}}}}},
 {{{257,514,12,1040,2176,8224,4160}},46,{{27448,23068}},{{286467,265038}},{{{{{1,27448,117557}}},{{{1,23068,97658}}},{{{1,27448,119345}}},{{{1,23068,104242}}}}}},
 {{{384,514,12,3072,17,8224,4160}},46,{{52144,33808}},{{413174,202572}},{{{{{1,26000,112466},{26001,52144,115626}}},{{{1,17000,77781},{17001,33808,77912}}},{{{1,26000,116189},{26001,52144,108603}}},{{{1,17000,76040},{17001,33808,73980}}}}}},
 {{{3,768,1028,2056,144,8224,4160}},40,{{26364,12620}},{{280846,152594}},{{{{{1,26364,103599}}},{{{1,12620,48299}}},{{{1,26364,98432}}},{{{1,12620,55778}}}}}},
 {{{257,514,12,3072,144,8224,4160}},40,{{40392,15248}},{{390380,166320}},{{{{{1,20000,72817},{20001,40392,82237}}},{{{1,15248,59694}}},{{{1,20000,79933},{20001,40392,88005}}},{{{1,15248,67590}}}}}},
 {{{384,514,1028,2056,17,8224,4160}},40,{{13624,40276}},{{140786,331240}},{{{{{1,13624,52378}}},{{{1,20000,79655},{20001,40276,80137}}},{{{1,13624,52825}}},{{{1,20000,73708},{20001,40276,73713}}}}}}
}};
int main(int argc,char**argv){assert(argc==4);int ci=std::stoi(argv[1]),ori=std::stoi(argv[2]),si=std::stoi(argv[3]);assert(ci>=0&&ci<(int)CASES.size()&&ori>=0&&ori<4);auto const&data=CASES[ci];assert(si>=0&&si<(int)data.shards[ori].size());S c=centre();E e;e.s=c;e.h=host();e.run();auto r1=e.ns;assert(r1.size()==364);std::unordered_set<S,Hash>r2;for(auto const&p:r1){e.s=p;e.run();for(auto const&v:e.ns)if(v!=c&&!r1.count(v))r2.insert(v);}assert(r2.size()==26550);std::unordered_set<S,Hash>r3;for(auto const&p:r2){e.s=p;e.run();for(auto const&v:e.ns)if(v!=c&&!r1.count(v)&&!r2.count(v)&&supp(c,v)==20)r3.insert(v);}assert(r3.size()==71860);std::vector<S>group;for(auto const&s:r3){bool ok=true;for(int i=0;i<7;i++)ok&=s[i]==data.sig[i];if(ok)group.push_back(s);}std::sort(group.begin(),group.end());assert((int)group.size()==data.multiplicity);TopEnum top;top.sig=data.sig;top.run(ori%2);assert((int)top.sol.size()==data.top_orders[ori%2]);assert(top.nodes==data.top_nodes[ori%2]);auto shard=data.shards[ori][si];assert(shard.first>=1&&shard.last<=(int)top.sol.size());std::uint64_t total=0;for(int i=shard.first-1;i<shard.last;i++){BottomGroup bottom;assert(!bottom.solve(group,top.sol[i],ori));total+=bottom.nodes;}assert(total==shard.nodes);std::cout<<"case="<<ci<<" multiplicity="<<data.multiplicity<<" orientation="<<ori<<" shard="<<si<<" range="<<shard.first<<"-"<<shard.last<<" bottom_nodes="<<total<<" PASS\n";}
